from __future__ import annotations

from html import escape
from urllib.parse import quote

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .tenant_storage import project_path

router = APIRouter()


@router.get("/song-editor/{project_name}/audition", response_class=HTMLResponse, include_in_schema=False)
def song_edit_audition(project_name: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse(
            f"/signin?next=/song-editor/{quote(project_name, safe='')}/audition",
            status_code=303,
        )
    try:
        project_path(project_name, must_exist=True)
    except Exception:
        return HTMLResponse("<h1>Project not found</h1>", status_code=404)
    encoded = quote(project_name, safe="")
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Song Edit Audition — __BRAND__</title><style>
:root{--bg:#03040a;--panel:#0d1120;--line:#ffffff20;--gold:#e9c86f;--violet:#9a6dff;--cyan:#55dcff;--green:#72e0a8;--red:#ff8fa5;--muted:#bac1d4;--text:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,#40176b66,transparent 28%),radial-gradient(circle at 94% 2%,#153f7966,transparent 25%),linear-gradient(#020309,#070913 65%,#020309);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}.wrap{width:min(1450px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bef;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.65rem;text-transform:uppercase;letter-spacing:.09em}.btn,button{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:11px;padding:9px 12px;font:inherit;font-weight:850;cursor:pointer}.btn.primary,button.primary{border:0;background:linear-gradient(115deg,var(--gold),var(--violet));color:#140d1b}.btn.good,button.good{border-color:#72e0a855;color:var(--green)}.btn.danger,button.danger{border-color:#ff8fa555;color:#ffd7df}.hero{padding:38px 0 18px}.eyebrow{font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);font-weight:950}h1{font-size:clamp(2.5rem,6vw,5.1rem);line-height:.94;letter-spacing:-.05em;margin:.14em 0 .2em}.lead,.muted{color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:12px;padding-bottom:60px}.card{border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#111628ed,#090c18f2);padding:16px;margin:10px 0}.directive{border:1px solid var(--line);border-radius:15px;padding:13px;background:#ffffff05;margin:9px 0}.row{display:flex;align-items:center;justify-content:space-between;gap:9px;flex-wrap:wrap}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:.7rem;margin:2px}.pill.ready{color:var(--green);border-color:#72e0a855}.pill.failed{color:#ffd5dd;border-color:#ff8fa555}.audio{width:100%;margin:10px 0}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:11px;margin:10px 0}.notice.show{display:block}.notice.bad{border-color:#ff8fa555;color:#ffd6de}input,textarea,select{width:100%;border:1px solid var(--line);border-radius:11px;padding:10px;background:#060912;color:#fff;font:inherit;outline:none}textarea{min-height:80px}.form{display:grid;gap:8px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.metric{border:1px solid var(--line);border-radius:14px;padding:11px;background:#ffffff05}.metric b{display:block;font-size:1.35rem}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed #ffffff2e;border-radius:14px}.guide{border-left:3px solid var(--cyan);padding-left:12px;margin:10px 0}.status{padding:10px;border-radius:12px;background:#ffffff05}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.78rem;overflow-wrap:anywhere}@media(max-width:950px){.grid{grid-template-columns:1fr}}@media(max-width:650px){.metrics{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/song-editor/__PROJECT__'>__BRAND__<small>Song DNA · Generate → Audition → Commit</small></a><div><a class='btn' href='/song-editor/__PROJECT__'>Song DNA</a> <a class='btn' href='/daw'>DAW</a> <a class='btn' href='/dashboard'>Dashboard</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Non-destructive release-grade music editing</div><h1 id='title'>Loading project…</h1><p class='lead'>Aura never replaces your current song just because you requested an edit. Generate a candidate, listen to it, reject/regenerate it if needed, and only then commit it into the DAW and remaster the song.</p><div id='notice' class='notice'></div></section><section class='grid'><div><div class='card'><div class='row'><div><div class='eyebrow'>Aura edit queue</div><h2>Auditionable candidates</h2></div><button class='btn' onclick='loadAll()'>Refresh</button></div><div id='directives'><div class='empty'>Loading edits…</div></div></div></div><aside><div class='card'><div class='eyebrow'>Performance-to-song input</div><h2>Give Aura your rhythm, hum or instrument.</h2><p class='muted'>Upload a tapped rhythm, beatbox, hummed melody, voice memo or real instrument performance. Aura analyses tempo/onsets, creates an editable MIDI guide where appropriate, and can apply the performance as a generation anchor while keeping the uploaded real audio.</p><form id='guideForm' class='form'><select name='kind'><option value='rhythm'>Tapped rhythm</option><option value='beatbox'>Beatbox</option><option value='hum'>Hum / sung melody</option><option value='melody'>Instrumental melody</option><option value='instrument'>Instrument performance</option><option value='voice_memo'>Voice memo / idea</option><option value='reference_audio'>Reference audio</option></select><input name='label' placeholder='Label, e.g. chorus guitar groove'><textarea name='intent' placeholder='Tell Aura how to use this performance'></textarea><input name='file' type='file' accept='audio/*' required><label class='muted'><input name='rights_confirmed' type='checkbox' value='true' required style='width:auto'> I own or have permission to use this audio.</label><button class='primary' type='submit'>Upload & analyse performance</button></form><div id='guideResult'></div></div><div class='card'><div class='eyebrow'>Performance guides</div><div id='guides'><div class='empty'>Loading guides…</div></div></div><div class='card'><div class='eyebrow'>Editing rules</div><div class='guide'><b>Lyrics</b><div class='muted'>Surgical vocal replacement requires verified phrase timing and a DAW-linked vocal track.</div></div><div class='guide'><b>Instruments</b><div class='muted'>Aura generates the new instrument against a context mix with the old layer muted.</div></div><div class='guide'><b>Sections</b><div class='muted'>Aura regenerates the selected verse, chorus or bridge as separate per-layer regional takes, builds a full-song audition mix, and leaves the active DAW untouched until Commit. If a track is currently an unconsolidated phrase comp, commit/consolidate one take first so no editable comp data is flattened.</div></div></div></aside></section></main><script>
const PROJECT='__PROJECT__', API=`/projects/${PROJECT}/song-dna`;
const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function notice(msg,bad=false){let n=$('notice');n.textContent=msg;n.className='notice show'+(bad?' bad':'');clearTimeout(window._t);window._t=setTimeout(()=>n.className='notice',7000)}async function json(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
let dna=null;
async function loadAll(){try{const d=await json(API);dna=d.song_dna;$('title').textContent=dna.title;renderDirectives();await loadGuides()}catch(e){notice(e.message,true)}}
function actionName(d){return ({replace_lyric_line:'Lyric phrase repair',replace_instrument:'Instrument replacement',regenerate_section:'Multitrack section regeneration'})[d.action]||d.action.replaceAll('_',' ')}
function renderDirectives(){if(!dna?.directives?.length){$('directives').innerHTML='<div class="empty">No planned Aura edits. Make a lyric, instrument or section change in Song DNA first.</div>';return}$('directives').innerHTML=[...dna.directives].reverse().map(d=>{const candidate=d.metadata?.candidate_path;const stream=`${API}/directives/${encodeURIComponent(d.id)}/candidate-audio`;const ready=d.status==='ready'&&candidate;const complete=d.status==='complete';const tracks=Number(d.metadata?.candidate_track_count||0);const sectionInfo=d.action==='regenerate_section'&&tracks?`<div class="status"><b>${tracks} editable layer candidate${tracks===1?'':'s'}</b> · full-song audition below · original DAW still active until Commit.</div>`:'';return `<div class="directive"><div class="row"><div><b>${esc(actionName(d))}</b><div><span class="pill ${d.status==='ready'?'ready':d.status==='failed'?'failed':''}">${esc(d.status)}</span><span class="pill code">${esc(d.id)}</span></div></div><div>${!complete&&d.status!=='rendering'?`<button class="primary" onclick="generate('${d.id}')">${ready?'Regenerate candidate':'Generate candidate'}</button>`:''}</div></div><p class="muted">${esc(d.instruction||'')}</p>${d.metadata?.last_error?`<div class="status" style="color:#ffd5dd">${esc(d.metadata.last_error)}</div>`:''}${sectionInfo}${ready?`<audio class="audio" controls preload="none" src="${stream}"></audio><div class="row"><button class="good" onclick="commit('${d.id}')">Commit this take & remaster</button><button class="danger" onclick="discard('${d.id}')">Reject candidate</button></div><p class="muted">The current active DAW take remains unchanged until Commit.</p>`:''}${complete?`<div class="status"><b style="color:var(--green)">Committed.</b> This candidate became the active take and the session was remastered through the technical quality gate. Perceptual listening review is still required.</div>`:''}${d.metadata?.execution_blocked_reason?`<div class="status muted">${esc(d.metadata.execution_blocked_reason)}</div>`:''}</div>`}).join('')}
async function generate(id){notice('Aura is generating a non-destructive candidate…');try{await json(`${API}/directives/${encodeURIComponent(id)}/generate`,{method:'POST'});await loadAll();notice('Candidate generated. Listen before committing.')}catch(e){await loadAll();notice(e.message,true)}}
async function discard(id){try{await json(`${API}/directives/${encodeURIComponent(id)}/discard`,{method:'POST'});await loadAll();notice('Candidate rejected. Original take remains active.')}catch(e){notice(e.message,true)}}
async function commit(id){if(!confirm('Commit this auditioned take into the DAW and remaster the song? The previous take is retained for rollback.'))return;notice('Committing take and running the release-quality gate…');try{const d=await json(`${API}/directives/${encodeURIComponent(id)}/commit`,{method:'POST'});await loadAll();notice(d.detail||'Candidate committed and remastered.')}catch(e){await loadAll();notice(e.message,true)}}
$('guideForm').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);$('guideResult').innerHTML='<p class="muted">Analysing tempo, rhythm and musical guide…</p>';try{const r=await fetch(`/projects/${PROJECT}/performance-inputs`,{method:'POST',credentials:'same-origin',body:fd});let b={};try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b.detail||`Upload failed (${r.status})`);const x=b.input;$('guideResult').innerHTML=`<div class="status"><b>${esc(x.label)}</b><div class="metrics" style="margin-top:8px"><div class="metric"><small class="muted">BPM</small><b>${esc(x.detected_bpm??'—')}</b></div><div class="metric"><small class="muted">Onsets</small><b>${esc(x.metadata?.onset_count??0)}</b></div><div class="metric"><small class="muted">MIDI guide</small><b>${x.midi_ref?'Yes':'—'}</b></div></div><p class="muted">${esc(x.generation_context)}</p><button class="good" onclick="applyGuide('${x.id}')">Use this to guide the song</button></div>`;e.target.reset();await loadGuides();notice('Performance analysed. Review and apply it when ready.')}catch(err){$('guideResult').innerHTML='';notice(err.message,true)}})
async function loadGuides(){try{const d=await json(`/projects/${PROJECT}/performance-inputs`);const rows=d.inputs||[];$('guides').innerHTML=rows.length?rows.slice().reverse().map(x=>`<div class="guide"><div class="row"><b>${esc(x.label)}</b><span class="pill">${esc(x.kind)}</span></div><div class="muted">${esc(x.detected_bpm??'—')} BPM · ${esc(x.metadata?.onset_count??0)} onsets · ${x.midi_ref?'editable MIDI guide':'audio guide'}</div><p class="muted">${esc(x.generation_context)}</p><div class="row"><span class="pill ${x.status==='applied'?'ready':''}">${esc(x.status)}</span>${x.status!=='applied'?`<button class="good" onclick="applyGuide('${x.id}')">Apply to project</button>`:''}</div></div>`).join(''):'<div class="empty">No performance guides uploaded yet.</div>'}catch(e){$('guides').innerHTML='<div class="empty">Unable to load guides.</div>'}}
async function applyGuide(id){try{const d=await json(`/projects/${PROJECT}/performance-inputs/${encodeURIComponent(id)}/apply`,{method:'POST'});await loadGuides();notice('Performance guide applied to the project DNA and generation context.')}catch(e){notice(e.message,true)}}
loadAll();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__PROJECT__", encoded)
        .replace("__PROJECT__", encoded)
        .replace("__PROJECT__", encoded)
        .replace("__BRAND__", escape(PRODUCT_FULL_NAME))
        .replace("__BRAND__", escape(PRODUCT_FULL_NAME))
    )
